task_input = [
    [0,5,0,0,0,0,0,5,0,0,5,0],
    [0,5,0,0,0,5,5,5,0,5,5,0],
    [5,5,5,0,0,5,0,5,5,5,0,0],
    [0,0,5,5,5,5,0,5,0,5,5,0],
    [0,0,0,5,0,0,0,5,0,0,5,0]
]

def solve(arc_grid):
    """Fill largest region of 0s with 8, smallest with 7"""
    rows = len(arc_grid)
    cols = len(arc_grid[0])

    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if arc_grid[r][c] == 0 and (r, c) not in visited:
                region = set()
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    rr, cc = stack.pop()
                    region.add((rr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if arc_grid[nr][nc] == 0 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
                regions.append(region)

    regions_sorted = sorted(regions, key=len, reverse=True)
    largest = regions_sorted[0]
    smallest = regions_sorted[-1]

    result = [row[:] for row in arc_grid]

    for region in regions:
        if region == smallest:
            for (r, c) in region:
                result[r][c] = 7
        elif region == largest:
            for (r, c) in region:
                result[r][c] = 8

    return result, regions, largest, smallest

result, regions, largest, smallest = solve(task_input)

print("Task input regions (sorted by size):")
for i, region in enumerate(regions):
    print(f"Region {i}: {len(region)} cells at {sorted(region)}")

print("\n\nAnswer for test input:")
for row in result:
    print(' '.join(map(str, row)))
